export const groupSummaries: GroupSummary[] = [
  {
    id: 'grupo-i', numeral: 'I', title: 'Organización del Estado, la Unión Europea y la Administración territorial',
    question: '¿Quién manda, qué puede hacer cada institución y cómo encaja Burgos dentro del Estado?',
    overview: [
      'Este grupo dibuja el mapa institucional. La Constitución es el punto de partida: crea los poderes del Estado, reconoce derechos y organiza territorialmente España. Después sitúa al Estado, las comunidades autónomas, los municipios y la Unión Europea.',
      'La idea que une los nueve temas es la competencia. No basta con que una medida parezca útil: debe adoptarla la institución y el órgano que tengan atribuida esa materia. Burgos es un municipio, forma parte de Castilla y León, del Estado español y de la Unión Europea; cada nivel tiene normas, órganos y competencias diferentes.',
    ],
    route: 'Constitución → poderes del Estado → territorio → Administración del Estado → régimen local → municipio → Ayuntamiento de Burgos → Unión Europea → Castilla y León.',
    laws: [
      { name: 'Constitución Española', date: '27 de diciembre de 1978', role: 'Norma suprema: derechos, poderes del Estado, organización territorial y autonomía local.' },
      { name: 'Ley 7/1985, Reguladora de las Bases del Régimen Local', date: '2 de abril de 1985', role: 'Norma básica de municipios, provincias, órganos, competencias y servicios locales.' },
      { name: 'Real Decreto 2568/1986 (ROF)', date: '28 de noviembre de 1986', role: 'Desarrolla la organización y el funcionamiento de las entidades locales.' },
      { name: 'Estatuto de Autonomía de Castilla y León, Ley Orgánica 14/2007', date: '30 de noviembre de 2007', role: 'Norma institucional básica de Castilla y León; reforma el Estatuto originario de 1983.' },
      { name: 'Tratado de la Unión Europea y Tratado de Funcionamiento de la UE', date: 'versión de Lisboa, 13 de diciembre de 2007', role: 'Ordenan las instituciones y competencias de la Unión; entraron en vigor el 1 de diciembre de 2009.' },
    ],
    topics: [
      { number: 1, title: 'Constitución: estructura, principios y derechos', explanation: ["Constitución: es la norma suprema; vincula a ciudadanía y poderes públicos. España es un Estado social y democrático de Derecho, con monarquía parlamentaria.","Valores del art. 1: libertad, justicia, igualdad y pluralismo político. La soberanía nacional reside en el pueblo español.","Estructura: preámbulo, título preliminar, diez títulos y disposiciones. Tiene 169 artículos.","Derechos y garantías: los arts. 14 a 29 tienen tutela judicial preferente y sumaria y, cuando procede, amparo constitucional. El amparo también alcanza la objeción de conciencia del art. 30.2; no todos los derechos del Título I tienen idénticas garantías.","Suspensión: el art. 55 contempla determinados derechos y supuestos, no una suspensión general automática de todos los derechos.","Fechas: referéndum el 6 de diciembre de 1978; sanción el 27; publicación y entrada en vigor el 29 de diciembre."], example: 'Una ordenanza que discrimine por razón de sexo podría ser anulada porque toda norma local está subordinada a la Constitución.', keys: ['Título preliminar: arts. 1-9.', 'Derechos y deberes: arts. 10-55.', 'Reforma: arts. 166-169; procedimientos ordinario y agravado.'] },
      { number: 2, title: 'Corona, Cortes, Gobierno y Poder Judicial', explanation: ["Corona: el Rey es jefe del Estado y arbitra y modera el funcionamiento de las instituciones. Sus actos requieren refrendo, salvo la excepción constitucional del art. 65.2.","Cortes Generales: Congreso y Senado representan al pueblo, legislan, aprueban presupuestos y controlan al Gobierno.","Gobierno: dirige la política interior y exterior y la Administración; ejerce la función ejecutiva y la potestad reglamentaria.","Poder Judicial: jueces y magistrados independientes juzgan y hacen ejecutar lo juzgado. El CGPJ gobierna el Poder Judicial, pero no es un tribunal.","Investidura: el Congreso otorga confianza al candidato a presidente; primero se exige mayoría absoluta y, en segunda votación 48 horas después, mayoría simple.","Control político: la moción de censura propone un candidato alternativo y necesita mayoría absoluta; la cuestión de confianza la plantea el presidente y requiere mayoría simple."], example: 'El Gobierno presenta un proyecto de ley, las Cortes lo aprueban y el Rey lo sanciona y promulga con el refrendo correspondiente.', keys: ['Corona: Título II.', 'Cortes: Título III.', 'Gobierno: Título IV; Poder Judicial: Título VI.'] },
      { number: 3, title: 'Organización territorial y comunidades autónomas', explanation: ["Organización territorial: municipios, provincias y comunidades autónomas tienen autonomía para gestionar sus intereses.","Estado y comunidades: los arts. 148 y 149 CE y los estatutos sirven para identificar quién puede regular y ejecutar cada materia.","Estatuto: es la norma institucional básica de la comunidad autónoma, aprobada mediante ley orgánica y subordinada a la Constitución.","Competencia exclusiva: un nivel asume las funciones atribuidas sobre una materia. Hay que leer exactamente su alcance y sus límites.","Competencia compartida: por ejemplo, el Estado fija bases y la comunidad las desarrolla; competencia ejecutiva significa aplicar o gestionar la normativa correspondiente."], example: 'El Estado fija legislación básica en una materia y Castilla y León puede desarrollarla y ejecutarla si su Estatuto le atribuye competencia.', keys: ['Autonomía no significa soberanía.', 'La competencia puede ser exclusiva, compartida o ejecutiva.', 'Municipio y provincia también tienen autonomía garantizada.'] },
      { number: 4, title: 'Gobierno y Administración del Estado', explanation: ["Gobierno: toma decisiones de dirección política. Administración: ejecuta las funciones públicas y sirve objetivamente al interés general.","Art. 103 CE: eficacia, jerarquía, descentralización, desconcentración, coordinación y sometimiento pleno a la ley y al Derecho.","Administración central: se organiza principalmente en ministerios y sus órganos superiores y directivos.","Administración territorial del Estado: delegados del Gobierno en las comunidades y subdelegados en las provincias, según su régimen.","Descentralización: distribuye funciones entre distintas entidades; desconcentración las distribuye entre órganos de una misma Administración."], example: 'Un ministro fija la dirección política de su departamento, mientras sus órganos tramitan expedientes y aplican las normas.', keys: ['Dirección política frente a gestión administrativa.', 'La Administración tiene personalidad jurídica y actúa por órganos.', 'Toda potestad necesita atribución normativa.'] },
      { number: 5, title: 'Entidades locales y régimen local', explanation: ["Entidades territoriales básicas: municipio, provincia e isla. También existen comarcas, áreas metropolitanas y mancomunidades en los términos legales.","Autonomía local: capacidad de gestionar intereses propios dentro de la ley; no equivale a independencia del Estado.","Competencias: pueden ser propias o delegadas; ejercer otras distintas exige las condiciones del art. 7.4 LRBRL.","Servicios mínimos: el art. 26 LRBRL exige servicios según tramos de población; no todos los municipios tienen las mismas obligaciones.","Financiación: tributos propios, participación en ingresos de otras Administraciones, subvenciones y otros recursos previstos por la ley."], example: 'El Ayuntamiento puede prestar recogida de residuos porque es una materia local y debe financiar el servicio conforme al ordenamiento.', keys: ['LRBRL: Ley 7/1985.', 'Autonomía = capacidad de gestión dentro de la ley.', 'Competencias propias, delegadas y distintas de las propias con requisitos.'] },
      { number: 6, title: 'Municipio, territorio y población', explanation: ["Elementos del municipio: territorio, población y organización. Si te preguntan por ellos, recuerda las tres piezas juntas.","Término municipal: territorio en el que el Ayuntamiento ejerce sus competencias.","Población: conjunto de personas inscritas en el padrón; la condición de vecino se adquiere al inscribirse.","Padrón: registro administrativo que acredita residencia y domicilio habitual. Si se vive en varios municipios, corresponde aquel donde se pasa más tiempo al año.","Límites del padrón: no acredita propiedad de una vivienda y, para extranjeros, no prueba por sí solo residencia legal en España."], example: 'Quien vive habitualmente en Burgos debe empadronarse allí, aunque tenga una vivienda en otro municipio.', keys: ['Vecino es quien está inscrito en el padrón.', 'El padrón no concede por sí solo nacionalidad ni propiedad.', 'Las alteraciones del término municipal siguen procedimiento legal.'] },
      { number: 7, title: 'Organización del Ayuntamiento de Burgos', explanation: ["Régimen de Burgos: municipio de gran población; se aplican las especialidades del Título X LRBRL y su Reglamento Orgánico Municipal.","Pleno: representación política, normas municipales, presupuesto y control del gobierno municipal.","Alcalde y tenientes de alcalde: el alcalde dirige y representa al Ayuntamiento; los tenientes lo sustituyen en los supuestos legales.","Junta de Gobierno Local: órgano colegiado de dirección ejecutiva con competencias propias relevantes; no es simplemente una comisión informativa.","Secretaría del Pleno y Asesoría Jurídica: fe pública y asesoramiento en sus ámbitos respectivos.","Intervención, gestión tributaria y Tesorería: control económico, gestión de tributos y manejo de fondos, respectivamente. Son funciones distintas."], example: 'La Junta prepara o aprueba actuaciones ejecutivas, el Pleno aprueba una ordenanza y la Intervención fiscaliza los efectos económicos.', keys: ['Separar órganos políticos de órganos técnicos.', 'No atribuir automáticamente todo al alcalde o al Pleno.', 'Consultar LRBRL y Reglamento Orgánico Municipal.'] },
      { number: 8, title: 'Unión Europea', explanation: ["Consejo Europeo: reúne a jefes de Estado o de Gobierno y fija grandes orientaciones políticas; no ejerce función legislativa.","Consejo de la UE: reúne a ministros de los Estados según la materia; normalmente colegisla con el Parlamento.","Parlamento Europeo: representa a la ciudadanía, colegisla, comparte la función presupuestaria y ejerce control político.","Comisión: propone legislación y vigila el cumplimiento del Derecho de la Unión.","TJUE, BCE y Tribunal de Cuentas: interpretación y aplicación del Derecho, política monetaria del euro y control de las finanzas de la Unión.","Normas europeas: el reglamento es directamente aplicable; la directiva obliga a un resultado y normalmente requiere transposición; la decisión es obligatoria en sus términos.","Consejo de Europa: es una organización internacional distinta de la UE; no lo confundas con sus dos Consejos."], example: 'Una directiva obliga a alcanzar un resultado y normalmente necesita transposición; un reglamento europeo es directamente aplicable.', keys: ['No confundir Consejo Europeo, Consejo de la UE y Consejo de Europa.', 'Parlamento + Consejo ejercen normalmente la función legislativa.', 'La Comisión no es el Gobierno de España ni representa a los Estados.'] },
      { number: 9, title: 'Castilla y León y su Estatuto', explanation: ["Estatuto: organiza Castilla y León, reconoce derechos y principios y determina sus competencias dentro de la Constitución.","Cortes de Castilla y León: representan al pueblo de la Comunidad, legislan, aprueban presupuestos y controlan a la Junta.","Presidente: representa a la Comunidad y dirige la acción de la Junta.","Junta: órgano colegiado de gobierno y administración autonómica.","Reforma: necesita el procedimiento estatutario y aprobación mediante ley orgánica estatal; una norma autonómica ordinaria no basta."], example: 'Una ley autonómica debe respetar la Constitución, el Estatuto y el reparto de competencias con el Estado.', keys: ['Estatuto originario: LO 4/1983; reforma vigente principal: LO 14/2007.', 'Instituciones básicas: Cortes, presidente y Junta.', 'No confundir comunidad autónoma con provincia o municipio.'] },
    ],
    finalExample: 'Para abrir un centro municipal, la Constitución garantiza autonomía local, la LRBRL determina la competencia municipal, los órganos de Burgos adoptan los acuerdos y la normativa de Castilla y León o de la UE puede completar las condiciones aplicables.',
    memory: 'Grupo I = el mapa: Constitución, instituciones, territorios y competencias.',
  },
  {
    id: 'grupo-ii', numeral: 'II', title: 'Derecho y régimen jurídico de las Administraciones Públicas',
    question: '¿Cómo actúa legalmente el Ayuntamiento desde que nace una norma hasta que adopta, ejecuta o revisa una decisión?',
    overview: [
      'Este grupo cuenta la vida completa de una actuación administrativa. Primero averiguamos qué norma se aplica y qué órgano puede actuar. Después la Administración tramita un procedimiento y dicta un acto. Ese acto se notifica, produce efectos y puede recurrirse. Si causa un daño, puede generar responsabilidad.',
      'La segunda mitad aplica esa mecánica a actividades muy concretas: contratar, sancionar, administrar bienes, prestar servicios, reunirse y aprobar ordenanzas. La clave es no estudiar doce temas aislados, sino una cadena: norma, órgano, procedimiento, decisión, control y ejecución.',
    ],
    route: 'Fuente y competencia → procedimiento → acto y notificación → recurso o revisión → ejecución, sanción, contrato, patrimonio, servicio y norma local.',
    laws: [
      { name: 'Ley 39/2015 (LPAC)', date: '1 de octubre de 2015', role: 'Regula actos, interesados, plazos, procedimiento, silencio, ejecución y recursos. Entró en vigor, con carácter general, el 2 de octubre de 2016.' },
      { name: 'Ley 40/2015 (LRJSP)', date: '1 de octubre de 2015', role: 'Regula principios, órganos, competencia, sanciones, responsabilidad, convenios y relaciones entre Administraciones.' },
      { name: 'Ley 29/1998', date: '13 de julio de 1998', role: 'Regula el control judicial contencioso-administrativo.' },
      { name: 'Ley 9/2017 (LCSP)', date: '8 de noviembre de 2017', role: 'Regula contratos públicos; entró en vigor el 9 de marzo de 2018.' },
      { name: 'Ley 7/1985 y reglamentos locales de 1986', date: '2 de abril de 1985 y 1986', role: 'Aportan las especialidades municipales de órganos, bienes, servicios y ordenanzas.' },
    ],
    topics: [
      { number: 1, title: 'Fuentes del Derecho administrativo', explanation: ["Fuentes: ley, costumbre y principios generales del Derecho; la jurisprudencia complementa el ordenamiento.","Jerarquía: Constitución, normas con rango de ley y reglamentos. Entre Estado y comunidad autónoma también importa la competencia, no solo el rango.","Ley orgánica: materias constitucionalmente reservadas; mayoría absoluta del Congreso en votación final sobre el conjunto.","Decreto-ley: el Gobierno responde a extraordinaria y urgente necesidad; el Congreso decide su convalidación o derogación en 30 días.","Decreto legislativo: el Gobierno legisla por delegación de las Cortes; puede elaborar un texto articulado o refundir textos según la autorización.","Reglamento: norma general de la Administración subordinada a la ley; una resolución particular no puede dispensar de cumplirlo.","Unión Europea: su primacía de aplicación en su ámbito no debe confundirse con una simple escala de rangos internos."], example: 'Una ordenanza de Burgos no puede crear libremente una sanción sin cobertura legal ni contradecir una ley estatal o autonómica.', keys: ['Entrada ordinaria de las leyes: 20 días tras publicación completa, salvo previsión distinta.', 'Decreto-ley = urgencia; decreto legislativo = delegación.', 'Reglamento ilegal: nulidad de pleno derecho.'] },
      { number: 2, title: 'Acto administrativo: la decisión concreta', explanation: ["Concepto: declaración de la Administración que aplica el Derecho a un caso, como una licencia, multa, nombramiento o subvención.","Clases: favorable o de gravamen; expreso o presunto; de trámite o definitivo. Un acto que agota la vía administrativa todavía puede ser recurrible: no equivale a acto firme.","Requisitos: órgano competente, contenido posible y legal, finalidad pública y procedimiento y forma exigidos.","Motivación: explica hechos y razones jurídicas; se exige, entre otros casos, al limitar derechos, resolver recursos o ejercer potestades discrecionales.","Validez: pregunta si el acto respeta el Derecho. Eficacia: pregunta desde cuándo produce efectos. Una notificación defectuosa no supone siempre que la decisión sea inválida.","Notificación: contiene texto íntegro, indicación de si agota vía y recursos con órgano y plazo. Debe cursarse en 10 días desde que se dicta; no equivale a exigir recepción dentro de esos 10 días.","Nulidad: defectos radicales tasados, como contenido imposible, lesión de derechos susceptibles de amparo o incompetencia manifiesta por materia o territorio.","Anulabilidad: otras infracciones relevantes. Un defecto formal solo invalida si falta un requisito indispensable o causa indefensión; hay irregularidades que no anulan el acto.","Convalidación: permite subsanar actos anulables cuando procede; no convierte un acto nulo en válido."], example: 'Si Urbanismo deniega una licencia, debe identificar el órgano, explicar la norma incumplida, notificar la resolución e indicar cómo recurrir. Si falta motivación y causa indefensión puede anularse; si decide un órgano manifiestamente incompetente por materia, puede haber nulidad.', keys: ['No confundir acto general con reglamento.', 'Validez responde a “¿nació legalmente?”; eficacia a “¿ya produce efectos?”.', 'Notificación defectuosa no convierte siempre el acto en nulo: puede retrasar su eficacia o los plazos de recurso.', 'Comprueba si el defecto es causa de nulidad, anulabilidad o irregularidad no invalidante.'] },
      { number: 3, title: 'Procedimiento administrativo común', explanation: ["Interesado: quien promueve el procedimiento como titular de derechos o intereses legítimos, o quien resulta afectado en los términos del art. 4 LPAC.","Derechos: conocer la tramitación, acceder al expediente, alegar, proponer prueba y no aportar documentos que ya obren en poder de la Administración en los términos legales.","Plazo máximo: el que fije la norma del procedimiento; normalmente no excede de 6 meses salvo habilitación legal o europea. Si no se fija, son 3 meses.","Silencio en solicitudes: la regla general es estimatoria, con excepciones como responsabilidad patrimonial, derecho de petición o transferencia de facultades de dominio público. Hay que comprobar siempre la norma aplicable.","Silencio de oficio: en procedimientos favorables, quienes comparecieron pueden entender desestimadas sus pretensiones; en sancionadores o de intervención desfavorable se produce caducidad en los términos legales.","Terminación: resolución, desistimiento, renuncia admisible, caducidad, acuerdo permitido o imposibilidad material. Desistir abandona la solicitud; renunciar abandona el derecho cuando es posible.","Cómputo: los días son hábiles salvo previsión de días naturales; meses y años se cuentan de fecha a fecha, con las reglas para días inexistentes o inhábiles."],
        steps: ["Iniciar: de oficio o a solicitud; subsanar, normalmente en 10 días, si falta información exigible.","Ordenar: impulsar el expediente de oficio y organizar trámites y documentos.","Instruir: alegaciones, prueba, informes y audiencia cuando corresponda.","Finalizar: resolver o aplicar otra forma legal de terminación y notificar.","Ejecutar: hacer efectivo lo decidido con los requisitos y medios legalmente admitidos."], example: 'Una solicitud de licencia entra en registro, se subsana, se piden informes, se oye al interesado, se resuelve y se notifica.', keys: ['Días administrativos: hábiles salvo que se diga naturales; no cuentan sábados, domingos ni festivos.', 'Audiencia suele ser de 10 a 15 días.', 'Silencio no libera a la Administración de resolver.'] },
      { number: 4, title: 'Revisión y recursos', explanation: ["Revisión de oficio: vía para declarar nulidad en los supuestos legales, normalmente con dictamen consultivo favorable; no es lo mismo que un recurso ordinario.","Lesividad: un acto favorable anulable no se retira libremente; la Administración declara su lesión al interés público dentro de 4 años y pide su anulación judicial.","Revocación: afecta a actos desfavorables con límites legales. Rectificación: corrige errores materiales, de hecho o aritméticos, no una nueva valoración jurídica.","Alzada: contra actos que no agotan vía; resuelve el superior jerárquico. Contra un acto expreso se interpone en un mes y se resuelve en tres.","Reposición: potestativa, contra actos que agotan vía; resuelve el mismo órgano. Un mes para interponer contra acto expreso y un mes para resolver.","Actos presuntos: alzada y reposición pueden interponerse en cualquier momento desde el día siguiente a los efectos del silencio, según sus reglas.","Revisión extraordinaria: contra actos firmes y por causas tasadas —error de hecho documental, documentos esenciales sobrevenidos, falsedad o conducta delictiva acreditadas—.","Contencioso: control judicial; el plazo ordinario contra acto expreso es de dos meses. Presentar un recurso administrativo no suspende automáticamente la ejecución."], example: 'Si el acto no agota la vía administrativa, procede alzada; si la agota, normalmente puede optarse por reposición o contencioso, sin perjuicio de regímenes especiales.', keys: ['Alzada: 1 mes contra acto expreso; resolución, 3 meses.', 'Reposición: 1 mes; resolución, 1 mes.', 'Contencioso contra acto expreso: normalmente 2 meses.', 'Extraordinario: error de hecho, 4 años; otras causas, 3 meses.'] },
      { number: 5, title: 'Órganos y competencia', explanation: ["Competencia: atribución legal de funciones a un órgano; es irrenunciable, aunque su ejercicio admita técnicas previstas por ley.","Delegación: otro órgano ejerce la competencia; su titularidad no cambia.","Avocación: el superior asume motivadamente uno o varios asuntos que normalmente resolvería un dependiente; en delegaciones sin dependencia, solo puede avocar el delegante.","Encomienda de gestión: encarga actividades materiales o técnicas; no transfiere la decisión jurídica ni la titularidad.","Delegación de firma: otro firma, pero la competencia y su ejercicio permanecen en el órgano delegante.","Suplencia: otra persona sustituye temporalmente al titular por vacante, ausencia, enfermedad u otras causas legales.","Imparcialidad: abstención si concurre una causa personal; recusación si la plantea el interesado. Interés personal, parentesco o amistad íntima pueden ser causas."], example: 'El concejal delegado puede resolver por delegación, pero el acto debe indicar esa circunstancia y se considera dictado por el delegante.', keys: ['No confundir titularidad con ejercicio.', 'Encomienda no permite ceder decisiones jurídicas.', 'Abstención la plantea el afectado; recusación puede promoverla el interesado.'] },
      { number: 6, title: 'Responsabilidad patrimonial', explanation: ["Daño efectivo: tiene que existir; una posibilidad futura no basta.","Valorable e individualizado: debe poder cuantificarse y afectar a una persona o grupo identificable.","Antijuridicidad: la persona no tiene el deber legal de soportar ese daño.","Causalidad: debe conectarse con el funcionamiento del servicio; una caída no genera automáticamente indemnización.","Exclusiones: fuerza mayor y daños que hay deber jurídico de soportar; la conducta de la víctima puede romper o moderar el nexo causal.","Reclamación: generalmente un año; en lesiones, desde curación o determinación de secuelas. El silencio a los seis meses es desestimatorio.","Autoridades y personal: el perjudicado reclama a la Administración; esta exige de oficio responsabilidad a su personal por dolo o culpa o negligencia graves cuando corresponda tras indemnizar."], example: 'Una caída por una baldosa municipal rota puede dar derecho a indemnización si se prueban defecto, lesión, cuantía y conexión causal.', keys: ['Norma sustantiva: arts. 32-37 LRJSP.', 'Procedimiento: Ley 39/2015.', 'Lesiones: el año comienza desde curación o determinación de secuelas.'] },
      { number: 7, title: 'Contratos del sector público', explanation: ["Finalidad: adquirir prestaciones públicas con publicidad, igualdad, transparencia e integridad; se busca la mejor relación calidad-precio según los criterios legales.","Tipos: obras construyen o reforman; suministro adquiere bienes; servicios contrata una actividad. Las concesiones trasladan riesgo operacional; el mixto combina prestaciones.","Partes: órgano de contratación y contratista con capacidad, solvencia y ausencia de prohibiciones. La mesa asiste, pero no sustituye al órgano que adjudica.","Importes: presupuesto base de licitación incluye IVA salvo disposición contraria; valor estimado excluye IVA e incorpora prórrogas y opciones previstas; precio es la contraprestación del contrato.","Expediente: acredita necesidad, objeto, crédito, presupuesto, duración, procedimiento, pliegos y criterios.","Adjudicación: abierto permite concurrir a cualquier empresario; restringido selecciona candidatos previamente; negociados requieren los supuestos legales.","Ejecución: se controla el cumplimiento; hay penalidades y modificaciones limitadas. El contrato se extingue por cumplimiento o resolución en las causas legales.","Contrato menor: no permite fraccionar; su duración no puede superar un año ni prorrogarse. El recurso especial solo cabe para contratos y actos legalmente incluidos."], example: 'Para contratar limpieza, el Ayuntamiento justifica la necesidad, aprueba pliegos y crédito, publica, valora ofertas, adjudica, formaliza y controla la ejecución.', keys: ['Contrato menor: obras inferiores a 40.000 €; suministro/servicio inferiores a 15.000 €, sin IVA.', 'Garantía definitiva ordinaria: 5 % del precio final ofertado, sin IVA.', 'No se puede fraccionar para eludir procedimiento.'] },
      { number: 8, title: 'Potestad sancionadora', explanation: ["Legalidad y tipicidad: debe existir cobertura normativa y descripción previa de la conducta; no se crean infracciones por analogía.","Irretroactividad: rige la norma del momento de los hechos, salvo aplicación de una posterior más favorable.","Culpabilidad y prueba: la Administración debe acreditar responsabilidad, respetando presunción de inocencia; no basta sospechar.","Proporcionalidad: la sanción se ajusta a gravedad y circunstancias. Non bis in idem impide duplicar castigo cuando coinciden sujeto, hechos y fundamento.","Procedimiento: se inicia de oficio, separa instrucción y resolución, admite defensa y prueba y termina con resolución motivada.","Reducciones: en los casos del art. 85 LPAC, reconocimiento y pago voluntario permiten reducciones de al menos un 20 % cada una, acumulables y condicionadas a desistir o renunciar a acciones o recursos administrativos contra la sanción.","Prescripción y caducidad: prescripción limita perseguir la infracción o ejecutar la sanción; caducidad archiva un expediente por vencimiento, sin impedir uno nuevo si todavía no ha prescrito.","Plazos supletorios: infracciones muy graves 3 años, graves 2 y leves 6 meses; sanciones muy graves 3 años, graves 2 y leves 1 año. Primero se comprueba la ley sectorial."], example: 'Ante ruido excesivo, el Ayuntamiento necesita ordenanza con cobertura legal, prueba válida, expediente, audiencia y resolución motivada.', keys: ['Prescripción supletoria de infracciones: 3 años muy graves, 2 graves, 6 meses leves.', 'Art. 141 LRBRL: máximos de 3.000 €, 1.500 € y 750 €, salvo previsión legal distinta, en el régimen local correspondiente.', 'Una sanción administrativa nunca puede privar de libertad.'] },
      { number: 9, title: 'Bienes de las entidades locales', explanation: ["Patrimonio: conjunto de bienes, derechos y acciones de la entidad local.","Dominio público: afectado a uso general o servicio público; una calle y una biblioteca son ejemplos.","Protección: inalienable significa que no se vende mientras conserve esa condición; inembargable, que no se embarga; imprescriptible, que un tercero no lo adquiere por el mero paso del tiempo.","Patrimoniales: sin afectación a uso o servicio público; pueden venderse, arrendarse o cederse con los requisitos del régimen aplicable.","Comunales: bienes cuyo aprovechamiento corresponde al común de los vecinos, con régimen especial.","Afectación y desafectación: incorporar o retirar un destino público; cambiar el destino público sin perder condición demanial es mutación demanial.","Usos: común general —caminar por una plaza—, común especial —por intensidad o peligrosidad— y privativo —ocupa y excluye a otros—. El título depende del uso y la normativa.","Defensa e inventario: investigar titularidad, deslindar límites, recuperar posesión y llevar inventario; la cesión gratuita o venta no es una decisión informal."], example: 'Una plaza es dominio público; un local municipal sin destino puede ser patrimonial; una terraza ocupa especialmente dominio público y necesita título.', keys: ['Inventario obligatorio, rectificación anual y comprobación al renovarse la Corporación.', 'Uso común general, común especial y privativo.', 'Investigación, deslinde, recuperación de oficio y desahucio protegen los bienes.'] },
      { number: 10, title: 'Actividad administrativa y servicios públicos', explanation: ["Limitación o policía: controla actividades para proteger intereses generales mediante licencias, órdenes e inspecciones.","Fomento: incentiva actividades privadas de interés general mediante ayudas y subvenciones.","Servicio público: el Ayuntamiento organiza, presta o garantiza una prestación de su competencia para atender necesidades colectivas.","Gestión directa: propia entidad, organismo autónomo, entidad pública empresarial local o sociedad mercantil local de capital íntegramente público.","Gestión indirecta: prestación mediante contratación en las formas legalmente admitidas; en concesión el contratista asume riesgo operacional.","Remunicipalización: pasar a gestión directa requiere analizar contrato, costes, personal, continuidad y viabilidad jurídica; no elimina obligaciones contractuales.","Iniciativa económica: desarrollar actividad económica pública exige justificar conveniencia, oportunidad y sostenibilidad; no toda empresa municipal presta un servicio reservado."], example: 'El autobús urbano puede gestionarlo una entidad municipal o un concesionario, pero el Ayuntamiento conserva titularidad, regulación y control.', keys: ['Debe elegirse la forma más sostenible y eficiente.', 'Servicio público no equivale a cualquier actividad económica.', 'Concesión implica riesgo operacional del concesionario.'] },
      { number: 11, title: 'Órganos colegiados locales', explanation: ["Órganos: el Pleno adopta acuerdos dentro de sus competencias; la Junta tiene funciones ejecutivas; las comisiones preparan asuntos y emiten dictámenes.","Sesiones: ordinarias, extraordinarias y extraordinarias urgentes. La urgencia exige justificación y tratamiento conforme a las reglas legales.","Convocatoria: el Pleno se convoca con al menos dos días hábiles, salvo urgencia; se facilita orden del día y documentación.","Quórum: un tercio del número legal de miembros, nunca menos de tres, y presencia de presidente y secretario o sustitutos legales; debe mantenerse durante la sesión.","Mayoría simple: más votos a favor que en contra. Mayoría absoluta: más de la mitad del número legal de miembros, no solo de los asistentes.","Votación y acta: el voto puede ser ordinario, nominal o secreto en los supuestos admitidos; el acta documenta asistentes, deliberaciones esenciales y acuerdos."], example: 'Una propuesta se incluye en el orden del día, los concejales acceden al expediente, el Pleno debate, vota y Secretaría documenta el acuerdo.', keys: ['Las sesiones plenarias son públicas con excepciones.', 'Asunto fuera del orden del día exige urgencia en los casos permitidos.', 'No confundir dictamen de comisión con acuerdo del Pleno.'] },
      { number: 12, title: 'Ordenanzas, reglamentos y bandos', explanation: ["Ordenanza: norma municipal sobre materias locales, como convivencia o uso de espacios.","Reglamento: disposición general, frecuentemente sobre organización o funcionamiento de servicios. La diferencia de nombre no lo sitúa por encima de la ley.","Bando: instrumento de Alcaldía para comunicar o disponer en su ámbito; no sustituye una ordenanza ni su procedimiento.","Competencia: el Pleno aprueba ordenanzas y reglamentos; en gran población la Junta aprueba proyectos según la ley.","Fiscalidad: las ordenanzas fiscales siguen las especialidades de los arts. 15-19 TRLRHL.","Vigencia: aprobación y publicación son momentos distintos; para las ordinarias también se exige el transcurso del plazo legal de los arts. 65.2 y 70.2 LRBRL, computado desde la recepción de la comunicación del acuerdo por Estado y comunidad autónoma."],
        steps: ["Preparar proyecto, competencia e informes.","Aprobar inicialmente en el Pleno.","Abrir información pública y audiencia por un mínimo de 30 días.","Resolver reclamaciones y aprobar definitivamente; sin reclamaciones, la aprobación inicial queda definitiva.","Publicar íntegramente en el BOP y cumplir los requisitos de entrada en vigor."], example: 'Una ordenanza de convivencia se aprueba inicialmente, se expone al público, se contestan alegaciones y se publica antes de entrar en vigor.', keys: ['Ordenanzas fiscales: arts. 15-19 TRLRHL.', 'La publicación íntegra es necesaria.', 'Reglamento orgánico y ciertas decisiones exigen mayoría absoluta legal.'] },
    ],
    finalExample: 'Para crear una zona de bajas emisiones, el Ayuntamiento necesita cobertura normativa y competencia, tramita una ordenanza, adopta actos de aplicación, contrata medios técnicos, puede sancionar infracciones y debe responder si causa un daño antijurídico.',
    memory: 'Grupo II = la película de la actuación administrativa: norma, órgano, expediente, decisión, control y ejecución.',
  },
  {
    id: 'grupo-iii', numeral: 'III', title: 'Régimen jurídico de los empleados públicos',
    question: '¿Quién trabaja para la Administración, cómo accede, qué derechos y deberes tiene y qué ocurre durante su vida profesional?',
    overview: ['Este grupo sigue la vida laboral dentro del Ayuntamiento: selección, adquisición de la condición, puestos, carrera, situaciones, derechos, deberes, incompatibilidades y protección social.', 'La distinción decisiva es el vínculo: funcionario de carrera o interino se rige principalmente por Derecho administrativo; el personal laboral, por legislación laboral y convenios además de normas públicas; el eventual solo realiza confianza o asesoramiento especial.'],
    route: 'Clases de personal → acceso → puesto y carrera → situaciones → derechos colectivos e incompatibilidades → Seguridad Social.',
    laws: [
      { name: 'Real Decreto Legislativo 5/2015 (TREBEP)', date: '30 de octubre de 2015', role: 'Estatuto Básico del Empleado Público: clases, acceso, derechos, deberes, carrera y situaciones.' },
      { name: 'Ley 7/1985 y RDL 781/1986', date: '1985 y 1986', role: 'Especialidades del personal de las entidades locales.' },
      { name: 'Real Decreto Legislativo 2/2015, Estatuto de los Trabajadores', date: '23 de octubre de 2015', role: 'Norma básica del personal laboral.' },
      { name: 'Ley 53/1984, de incompatibilidades', date: '26 de diciembre de 1984', role: 'Impide conflictos entre empleo público y otras actividades.' },
      { name: 'Real Decreto Legislativo 8/2015, Ley General de la Seguridad Social', date: '30 de octubre de 2015', role: 'Afiliación, cotización, contingencias y prestaciones.' },
    ],
    topics: [
      { number: 1, title: 'Clases, provisión, derechos y carrera', explanation: ["Funcionario de carrera: vínculo estatutario permanente para servicios profesionales retribuidos.","Funcionario interino: nombramiento temporal por necesidad y urgencia en causas legales; no adquiere automáticamente condición de carrera.","Personal laboral: vínculo mediante contrato de trabajo; personal eventual: confianza o asesoramiento especial, con nombramiento y cese libres.","Acceso: entrar al empleo público mediante selección con igualdad, mérito, capacidad y publicidad; oposición, concurso-oposición y concurso en los supuestos permitidos.","Provisión: asignar puestos a quienes ya reúnen los requisitos; concurso y libre designación con convocatoria pública, según el puesto.","Carrera y promoción: progresar profesionalmente o acceder a otro cuerpo, escala o subgrupo. Acceder, ocupar un puesto y promocionar son operaciones distintas.","Derechos: retribución, formación, descanso, conciliación, intimidad y derechos colectivos; deberes: objetividad, imparcialidad, confidencialidad, diligencia y servicio al interés general.","Disciplina: un incumplimiento puede generar responsabilidad disciplinaria con garantías; la inamovilidad protege la condición de carrera, no cualquier puesto concreto."], example: 'Una oposición selecciona funcionarios; un concurso posterior cubre un puesto concreto entre quienes ya reúnen los requisitos.', keys: ['Interino: razones temporales legalmente tasadas.', 'Eventual: confianza o asesoramiento, no funciones permanentes ordinarias.', 'Derechos individuales conviven con deberes y código de conducta.'] },
      { number: 2, title: 'Adquisición, pérdida y situaciones', explanation: ["Adquisición: exige completar el proceso selectivo, nombramiento publicado, acatamiento de Constitución y ordenamiento y toma de posesión en plazo.","Pérdida: renuncia aceptada, pérdida de la nacionalidad exigida, jubilación, separación firme del servicio o pena de inhabilitación en los términos legales.","Servicio activo: ejercicio ordinario de funciones con los derechos y deberes correspondientes.","Servicios especiales: determinados cargos o funciones legalmente previstos; con efectos específicos de cómputo y reingreso.","Servicio en otras Administraciones: movilidad entre Administraciones manteniendo el régimen legal de vinculación y derechos.","Excedencia: causas diversas —interés particular, agrupación familiar, cuidados y otras— con efectos diferentes sobre retribución y reserva; no hay una única regla para todas.","Suspensión: priva temporalmente del ejercicio de funciones; provisional y firme responden a situaciones diferentes."],
        steps: ["Superar el proceso selectivo.","Obtener nombramiento publicado oficialmente.","Acreditar el acatamiento de la Constitución y del ordenamiento mediante juramento o promesa.","Tomar posesión dentro del plazo."], example: 'Una persona que supera el proceso pero no toma posesión en plazo no completa la adquisición de la condición, salvo causa admitida.', keys: ['Perder el puesto no es necesariamente perder la condición.', 'Suspensión provisional y firme no son iguales.', 'Cada excedencia tiene causa y efectos propios.'] },
      { number: 3, title: 'Personal laboral', explanation: ["Vínculo: contrato escrito de trabajo; puede ser fijo, por tiempo indefinido o temporal.","Normas: Estatuto de los Trabajadores, convenio, contrato y preceptos aplicables del TREBEP; ser personal público añade exigencias de acceso y conducta.","Selección: igualdad, mérito, capacidad y publicidad; un contrato laboral municipal no permite contratar libremente sin proceso.","Funciones reservadas: las que implican ejercicio de potestades públicas o salvaguardia de intereses generales se reservan a funcionarios en los términos legales.","Derechos y deberes: jornada, retribución, descanso, negociación y disciplina se estudian según las normas aplicables; también existen incompatibilidades.","Fijo e indefinido no fijo: no son categorías intercambiables; una irregularidad temporal no convierte automáticamente al trabajador en personal fijo."], example: 'Un operario municipal laboral puede acceder mediante proceso público, pero su jornada y clasificación se concretan también en el convenio.', keys: ['Laboral fijo no equivale a funcionario.', 'El convenio no puede contradecir normas imperativas.', 'La temporalidad necesita causa legal.'] },
      { number: 4, title: 'Sindicación, huelga e incompatibilidades', explanation: ["Libertad sindical: permite afiliación, actividad sindical y defensa colectiva, con especialidades según colectivos.","Negociación: aborda condiciones de trabajo dentro de la ley y límites presupuestarios; no permite pactar contra normas obligatorias.","Huelga: derecho con garantías para mantener servicios esenciales; servicios mínimos no significan prohibición total de huelga.","Incompatibilidad pública: desempeñar un segundo puesto público es excepcional y requiere cobertura y autorización.","Actividad privada: se comprueba conflicto con asuntos gestionados, imparcialidad, horario y restricciones legales; cuando procede, requiere reconocimiento previo de compatibilidad.","Actividades exceptuadas: la Ley 53/1984 contempla algunas, por lo que no toda actividad externa exige idéntico trámite."], example: 'Un empleado que informa expedientes de una empresa no puede asesorarla privadamente porque existiría conflicto de interés.', keys: ['Ley Orgánica 11/1985: libertad sindical.', 'Real Decreto-ley 17/1977: huelga, interpretado conforme a la Constitución.', 'Ley 53/1984: incompatibilidades.'] },
      { number: 5, title: 'Seguridad Social', explanation: ["Estructura: Régimen General y regímenes especiales; nivel contributivo ligado a cotizaciones y no contributivo ligado a requisitos específicos de protección.","Afiliación: identificación única en el sistema; alta y baja reflejan inicio y fin de una actividad; cotización financia la protección.","Contingencias comunes: enfermedad común o accidente no laboral; profesionales: accidente de trabajo y enfermedad profesional.","Incapacidad temporal: imposibilidad transitoria para trabajar; incapacidad permanente: reducciones funcionales previsiblemente definitivas en los grados legales.","Acción protectora: asistencia sanitaria y prestaciones por incapacidad, nacimiento y cuidado, desempleo, jubilación y muerte y supervivencia, entre otras.","Gestión: INSS reconoce y gestiona muchas prestaciones; TGSS gestiona afiliación y recaudación; otras entidades actúan según la prestación.","Requisitos: estar afiliado o en alta no basta siempre; determinadas prestaciones exigen períodos cotizados u otras condiciones."], example: 'Una lesión en el trabajo puede ser accidente laboral; una enfermedad sin relación profesional es contingencia común.', keys: ['Afiliación es única y vitalicia; alta y baja cambian con la actividad.', 'Empresa y trabajador cotizan en los términos legales.', 'Incapacidad temporal y permanente tienen requisitos y efectos distintos.'] },
    ],
    finalExample: 'El Ayuntamiento publica una convocatoria, selecciona por mérito y capacidad, nombra y da posesión; después provee puestos, reconoce derechos y carrera, controla incompatibilidades y cotiza para la protección social.',
    memory: 'Grupo III = la vida de quien trabaja en la Administración: entrar, trabajar, progresar, cambiar de situación y quedar protegido.',
  },
  {
    id: 'grupo-iv', numeral: 'IV', title: 'Gestión financiera y urbanismo',
    question: '¿De dónde obtiene dinero el Ayuntamiento, cómo lo gasta y controla, y cómo ordena el suelo y las obras?',
    overview: ['Los cuatro primeros temas forman un circuito económico: ingreso local, presupuesto, ejecución del gasto y control. El quinto aplica potestades públicas al territorio y a la disciplina urbanística.', 'La idea esencial es que el dinero público no se maneja como dinero privado: todo ingreso y gasto necesita norma, competencia, presupuesto, expediente, contabilidad y control. En urbanismo tampoco basta ser propietario: el uso del suelo está limitado por el planeamiento.'],
    route: 'Tributos → presupuesto y crédito → autorización y pago → control interno y externo → suelo, licencia y disciplina.',
    laws: [
      { name: 'Real Decreto Legislativo 2/2004 (TRLRHL)', date: '5 de marzo de 2004', role: 'Haciendas locales, tributos, presupuesto, gasto y cuentas.' },
      { name: 'Real Decreto 500/1990', date: '20 de abril de 1990', role: 'Desarrolla presupuesto y modificaciones en las entidades locales.' },
      { name: 'Real Decreto 424/2017', date: '28 de abril de 2017', role: 'Régimen jurídico del control interno local.' },
      { name: 'Ley 7/1985', date: '2 de abril de 1985', role: 'Competencias y órganos locales con incidencia financiera.' },
      { name: 'Ley 5/1999 de Urbanismo de Castilla y León y Decreto 22/2004', date: '8 de abril de 1999 y 29 de enero de 2004', role: 'Régimen urbanístico autonómico aplicable en Burgos.' },
    ],
    topics: [
      { number: 1, title: 'Tributos locales y ordenanzas fiscales', explanation: ["Impuesto: grava una capacidad económica sin exigir servicio concreto a cambio; por ejemplo, IBI.","Tasa: puede exigirse por uso privativo o aprovechamiento especial del dominio público, o por servicios en las condiciones legales.","Precio público: se vincula a servicios voluntarios que también presta el sector privado; no es un tributo.","Contribución especial: exige beneficio especial o aumento de valor por una obra pública o establecimiento o ampliación de un servicio.","Impuestos obligatorios: IBI —inmuebles—, IAE —actividades económicas— e IVTM —vehículos—.","Impuestos potestativos: ICIO —construcciones, instalaciones y obras— e IIVTNU —incremento del valor de terrenos urbanos en los supuestos legales—.","Ordenanza fiscal: concreta lo permitido por la ley; exposición pública mínima de 30 días y publicación del texto definitivo. En Burgos hay que atender también a las especialidades de revisión económico-administrativa."], example: 'Ser propietario genera IBI; ocupar vía pública con terraza puede generar tasa; una obra que revaloriza especialmente fincas puede justificar contribuciones especiales.', keys: ['Potestad tributaria local siempre dentro de la ley.', 'Aprobación y exposición pública de ordenanzas fiscales.', 'Recurso contencioso directo contra la aprobación definitiva.'] },
      { number: 2, title: 'Presupuesto y modificaciones', explanation: ["Presupuesto: previsión de ingresos y autorización limitada de gastos para un ejercicio, normalmente el año natural.","Especialidad cualitativa: gastar en la finalidad autorizada; cuantitativa: hasta el crédito disponible; temporal: dentro del ejercicio salvo excepciones.","Crédito extraordinario: crea crédito que no existe para un gasto específico e inaplazable; suplemento: aumenta uno insuficiente y no ampliable.","Transferencia: mueve crédito entre aplicaciones; generación: lo incrementa por determinados ingresos; incorporación: traslada remanentes permitidos; ampliación: opera en créditos ampliables según las reglas.","Tramitación: elaboración, aprobación inicial, exposición de 15 días, reclamaciones, aprobación definitiva y publicación; si no hay reclamaciones se entiende definitivamente aprobado.","Prórroga: si no entra en vigor el nuevo, se prorroga el anterior con límites y exclusiones.","Gasto plurianual: compromete ejercicios futuros con condiciones, límites y subordinación a sus presupuestos; no es un permiso general para gastar sin crédito."], example: 'Si no existe partida para adquirir un vehículo, se necesita crédito extraordinario y financiación adecuada antes de comprometer la compra.', keys: ['Presupuesto general integra entidad, organismos y previsiones de sociedades.', 'Aprobación inicial, exposición 15 días y aprobación definitiva.', 'Prórroga presupuestaria no reproduce todos los créditos automáticamente.'] },
      { number: 3, title: 'Ejecución del gasto', explanation: ["RC —retención de crédito—: acredita disponibilidad para el gasto; es una operación previa, no una fase A-D-O-P.","A —autorización—: se decide realizar un gasto por importe determinado o estimado; todavía no se compromete con una empresa concreta.","D —disposición o compromiso—: se acuerda el gasto frente a un tercero, como al adjudicar un contrato.","O —reconocimiento de obligación—: se reconoce una deuda exigible tras acreditar la prestación y los requisitos.","P —ordenación del pago—: se emite la orden de satisfacer la obligación; el pago material es la salida posterior del dinero.","Competencia y documentos: cada fase debe realizarla el órgano competente y reflejarse contablemente; pueden acumularse fases cuando sea legalmente posible.","Excepciones reguladas: pagos a justificar y anticipos de caja fija tienen sus propias reglas de autorización, utilización y justificación."],
        steps: ["Comprobar y retener crédito: RC.","Autorizar el gasto: A.","Comprometerlo con un tercero: D.","Acreditar la prestación y reconocer la obligación: O.","Ordenar el pago: P.","Realizar el pago material."], example: 'Se autoriza contratar, se adjudica y compromete gasto, se reconoce obligación tras recibir correctamente el suministro, se ordena pagar y Tesorería realiza la transferencia.', keys: ['A no obliga frente a tercero; D sí compromete.', 'O exige prestación acreditada y conformidad.', 'P no es todavía el pago material.'] },
      { number: 4, title: 'Control del gasto público', explanation: ["Control interno: lo realiza la Intervención municipal; incluye función interventora y control financiero.","Función interventora: comprueba legalidad de los actos económicos en las fases correspondientes; no se reduce a revisar facturas.","Reparo: objeción de Intervención; suspende en los casos legales. La discrepancia se resuelve por el órgano competente, no ignorando el reparo.","Control financiero: control permanente y auditoría pública para revisar cumplimiento y gestión, con control de eficacia integrado.","Control externo: Tribunal de Cuentas y Consejo de Cuentas de Castilla y León dentro de sus competencias.","Seguimiento: informe-resumen anual de resultados y plan de acción para corregir deficiencias; controlar debe conducir a mejoras concretas."], example: 'Intervención detecta falta de crédito y formula reparo; posteriormente un control financiero evalúa si el servicio fue eficiente.', keys: ['Fiscalización previa y control posterior no son lo mismo.', 'Reparo suspensivo en supuestos legales.', 'Informe-resumen anual y plan de acción corrector.'] },
      { number: 5, title: 'Urbanismo y disciplina', explanation: ["Clasificación: categoría del suelo; la legislación urbanística de Castilla y León distingue suelo urbano, urbanizable y rústico con sus regímenes.","Calificación: usos, intensidades y condiciones que el planeamiento atribuye al suelo.","Planeamiento: determina la ordenación; el Ayuntamiento debe aplicar además la legislación estatal y autonómica pertinente.","Licencia: acto reglado que comprueba conformidad con la normativa; no se concede por mera conveniencia.","Declaración responsable: aplicable a actuaciones que la ley permite; no sustituye indiscriminadamente a toda licencia.","Restauración: paralizar, legalizar si procede o reponer la realidad alterada; sanción: castigar la infracción. Pueden coexistir porque cumplen fines diferentes."], example: 'Una ampliación sin licencia puede paralizarse, legalizarse si cumple el plan o demolerse si no; además puede imponerse sanción.', keys: ['La licencia urbanística es reglada.', 'Propiedad no equivale a libertad total de construcción.', 'Competencia municipal dentro de la legislación de Castilla y León.'] },
    ],
    finalExample: 'El Ayuntamiento recauda tributos, aprueba presupuesto, reserva crédito, contrata una obra, reconoce la obligación cuando se ejecuta, paga bajo control y verifica mediante licencia y disciplina que la actuación respeta el planeamiento.',
    memory: 'Grupo IV = el circuito del dinero público y el control del territorio.',
  },
  {
    id: 'grupo-v', numeral: 'V', title: 'Competencias prácticas y atención administrativa',
    question: '¿Cómo trabaja diariamente un administrativo con personas, documentos, datos y herramientas digitales?',
    overview: ['Es el grupo más cercano al puesto real y entra en test, práctico y desarrollo. Une derechos transversales —igualdad, transparencia, discapacidad, prevención y datos— con registro, expediente electrónico, archivo, Windows, Word, Excel, correo e Internet.', 'Su hilo es la atención segura: recibir a una persona, facilitar información accesible, registrar documentos, tramitar un expediente íntegro, proteger datos, usar herramientas corporativas y comunicar correctamente.'],
    route: 'Igualdad y derechos → transparencia y atención → registro → seguridad laboral y de datos → administración electrónica → documento y archivo → informática, ofimática, correo e Internet.',
    laws: [
      { name: 'Ley Orgánica 3/2007, igualdad efectiva', date: '22 de marzo de 2007', role: 'Igualdad y transversalidad en la actuación pública.' },
      { name: 'Ley Orgánica 1/2004 y Ley 4/2023', date: '28 de diciembre de 2004 y 28 de febrero de 2023', role: 'Protección contra violencia de género e igualdad real y efectiva LGTBI/trans.' },
      { name: 'Ley 19/2013, transparencia', date: '9 de diciembre de 2013', role: 'Publicidad activa, acceso a información y buen gobierno.' },
      { name: 'Ley 31/1995, prevención de riesgos laborales', date: '8 de noviembre de 1995', role: 'Evaluación, planificación, información, formación y vigilancia de la salud.' },
      { name: 'RGPD y Ley Orgánica 3/2018', date: '27 de abril de 2016 y 5 de diciembre de 2018', role: 'Principios, bases jurídicas, derechos y responsabilidades en datos personales.' },
      { name: 'Ley 39/2015, Ley 40/2015, ENI y ENS', date: '2015; RD 4/2010 y RD 311/2022', role: 'Relación electrónica, expediente, interoperabilidad y seguridad.' },
    ],
    topics: [
      { number: 1, title: 'Igualdad, violencia de género y derechos LGTBI', explanation: ["Igualdad formal: prohíbe discriminación; igualdad real: exige medidas para remover obstáculos.","Discriminación directa: trato peor por una causa protegida; indirecta: criterio aparentemente neutro que produce desventaja injustificada.","LO 3/2007: igualdad entre mujeres y hombres y perspectiva transversal en políticas y empleo público.","LO 1/2004: protección integral frente a la violencia de género en su ámbito legal, con derechos de información, asistencia y protección.","Ley 4/2023: igualdad de personas trans y garantía de derechos LGTBI; obliga a prevenir discriminación en la actuación pública.","Atención: respetar identidad e intimidad, evitar preguntas innecesarias y coordinar recursos para no hacer repetir constantemente situaciones traumáticas."], example: 'Una oficina adapta formularios, trato y derivación para que una víctima reciba atención confidencial y coordinada.', keys: ['Discriminación directa e indirecta.', 'Acoso sexual y por razón de sexo.', 'La igualdad es transversal, no exclusiva de servicios sociales.'] },
      { number: 2, title: 'Transparencia y acceso', explanation: ["Publicidad activa: publicar información institucional, normativa y económica sin solicitud previa.","Acceso: pedir información pública existente; no obliga a elaborar un informe nuevo para responder una consulta.","Solicitud: no exige motivación; debe identificar qué información se pide y permitir comunicar la respuesta.","Límites: se justifican y ponderan; si una parte puede entregarse sin lesionar el interés protegido, se valora acceso parcial.","Plazo: un mes desde recepción por el órgano competente, ampliable otro por volumen o complejidad si se comunica.","Silencio: desestimatorio. Puede utilizarse la reclamación de transparencia en los términos legales o la vía judicial.","Datos personales: transparencia no autoriza publicar indiscriminadamente; se aplican ponderación, disociación y garantías."], example: 'El Ayuntamiento publica contratos y presupuestos; una persona solicita además un expediente y se ocultan datos personales no necesarios.', keys: ['Publicidad activa ≠ solicitud de acceso.', 'Inadmisión ≠ aplicación de un límite.', 'Resolución general de acceso: un mes, ampliable otro por volumen o complejidad.'] },
      { number: 3, title: 'Atención al público, discapacidad, quejas y peticiones', explanation: ["Información general: trámites, requisitos, horarios y servicios; no exige acceso a datos personales de un expediente.","Información particular: situación y contenido de un expediente; requiere comprobar identidad y legitimación.","Accesibilidad: adaptar canales y comunicación y ofrecer ajustes razonables a personas con discapacidad.","Queja: protesta por el funcionamiento; sugerencia: propuesta de mejora.","Denuncia: comunica hechos que pueden justificar actuación administrativa; no convierte automáticamente al denunciante en interesado.","Recurso: impugna un acto en forma y plazo; petición: solicita actuación bajo el régimen específico del derecho de petición.","Límite de la atención: orientar con claridad sin prometer una resolución favorable ni revelar información reservada."], example: 'El personal explica cómo solicitar una ayuda y adapta la comunicación, pero no promete que será concedida ni revela el expediente a un tercero.', keys: ['Informar no es resolver.', 'Derecho de petición: LO 4/2001.', 'Queja no suspende ni sustituye recursos.'] },
      { number: 4, title: 'Oficinas de asistencia en materia de registros', explanation: ["Recepción: admitir y asentar escritos con fecha, hora y datos del registro; entregar justificante.","Digitalización: convertir documentos aportados en papel conforme a requisitos de copia auténtica; devolver originales cuando proceda.","Asistencia: ayudar a quienes tienen derecho a ello a identificarse, firmar y presentar electrónicamente; la firma por funcionario habilitado exige sus condiciones.","Representación: comprobar poder y alcance; ayudar a una persona no significa representar automáticamente su voluntad.","Registro electrónico: permite presentar 24 horas al día, pero el cómputo de plazos sigue las reglas de días hábiles.","Presentación presencial de un obligado electrónico: se requiere subsanar por vía electrónica y la fecha de presentación será la de esa subsanación según el art. 68.4 LPAC."], example: 'Una persona entrega papel; la oficina lo digitaliza, devuelve el original si procede y lo incorpora al sistema con fecha y hora acreditadas.', keys: ['Asistencia no siempre equivale a representación.', 'Digitalizar no es alterar el documento.', 'Fecha y hora de entrada pueden decidir si está en plazo.'] },
      { number: 5, title: 'Prevención de riesgos laborales', explanation: ["Objeto: evitar daños del trabajo mediante integración de la prevención, evaluación y planificación.","Orden preventivo: evitar riesgos, evaluar los inevitables, combatirlos en origen y adaptar el trabajo a la persona; prioridad de protección colectiva.","Obligaciones de la Administración: medios seguros, información, formación, medidas de emergencia y protección de la salud.","Obligaciones del trabajador: usar correctamente equipos, seguir instrucciones preventivas y comunicar riesgos.","Oficina: postura y pantalla, iluminación, caídas, carga mental y riesgos psicosociales necesitan medidas concretas.","Salud: vigilancia generalmente voluntaria, con excepciones legales; los datos médicos son confidenciales.","Participación: delegados de prevención y Comité de Seguridad y Salud en los términos legales."], example: 'Se ajustan silla y pantalla, se organizan pausas y se actúa ante acoso o sobrecarga mediante el protocolo correspondiente.', keys: ['Principios preventivos del art. 15 LPRL.', 'Protección colectiva antes que individual.', 'Vigilancia de la salud generalmente voluntaria, con excepciones legales.'] },
      { number: 6, title: 'Protección de datos', explanation: ["Base jurídica: debe existir una habilitación; en la Administración son frecuentes obligación legal o misión de interés público, sin pedir consentimiento por sistema.","Principios: finalidad concreta, datos mínimos, exactitud, conservación limitada, transparencia, seguridad y responsabilidad demostrable.","Responsable: decide fines y medios; encargado: trata por cuenta del responsable; delegado de protección de datos: asesora y supervisa.","Derechos: acceso, rectificación, supresión, oposición, limitación y portabilidad cuando proceda; no todos operan igual en cualquier tratamiento.","Categorías especiales: salud, datos biométricos de identificación y otras categorías requieren condiciones adicionales.","Brecha: pérdida, acceso o divulgación indebida; puede exigir notificación a la autoridad en 72 horas desde constancia, según el riesgo.","Trabajo diario: mínimo acceso necesario, destinatarios comprobados y conservación conforme al expediente, no copias privadas indefinidas."], example: 'Para tramitar una ayuda se piden solo datos necesarios, se limita el acceso y no se reutilizan para publicidad.', keys: ['Consentimiento no es la única base; en Administración son frecuentes obligación legal e interés público.', 'Brechas pueden exigir notificación en 72 horas.', 'Datos de salud son categoría especial.'] },
      { number: 7, title: 'Administración electrónica', explanation: ["Sede electrónica: dirección oficial con garantías de titularidad y responsabilidad; no equivale a cualquier página informativa.","Identificación: acredita quién actúa; firma: acredita voluntad y autenticidad en los trámites que la exigen.","Obligados: personas jurídicas y otros colectivos del art. 14.2 LPAC; las personas físicas conservan la elección salvo obligación aplicable.","Notificación: se practica al acceder al contenido. Si la vía es obligatoria o expresamente elegida, se entiende rechazada al pasar 10 días naturales sin acceso.","Aviso: el correo o SMS informa de una notificación disponible, pero no la sustituye; su ausencia no invalida por sí sola la notificación.","ENI: intercambio, interoperabilidad y conservación; ENS: protección y seguridad de sistemas e información.","CSV: código para comprobar autenticidad e integridad del documento a través del sistema habilitado."], example: 'Una empresa presenta solicitud en sede, firma electrónicamente, recibe puesta a disposición de la notificación y consulta su expediente.', keys: ['Identificación y firma no son siempre lo mismo.', 'Rechazo a los 10 días naturales sin acceso si la notificación electrónica es obligatoria o fue expresamente elegida.', 'Código Seguro de Verificación permite comprobar documentos.'] },
      { number: 8, title: 'Documento, expediente y archivo', explanation: ["Documento: información con contenido y contexto; su autenticidad, integridad y conservación deben poder acreditarse.","Expediente: conjunto ordenado de documentos y actuaciones que sirven de antecedente y fundamento de una resolución y de sus diligencias de ejecución.","Índice electrónico: identifica los documentos y, firmado, garantiza integridad del conjunto y permite recuperación.","Material auxiliar: notas, borradores y comunicaciones internas de apoyo no se incorporan automáticamente; ciertos informes sí son parte del expediente.","Archivo: clasifica, conserva, localiza y facilita acceso conforme a reglas; no es solo almacenar archivos en una carpeta.","Eliminación: requiere valoración y autorización según el régimen documental; cada empleado no decide qué documentos oficiales borrar."], example: 'Correos internos auxiliares no siempre forman parte del expediente; informes, solicitudes, pruebas y resolución sí cuando fundamentan la decisión.', keys: ['Expediente no es una carpeta desordenada.', 'Metadatos dan contexto y trazabilidad.', 'Eliminar documentos exige calendario y procedimiento, no decisión individual.'] },
      { number: 9, title: 'Informática y Windows 11', explanation: ["Hardware: componentes físicos; software: programas y sistemas que los hacen funcionar.","CPU: ejecuta instrucciones; RAM: memoria de trabajo temporal; disco o SSD: almacenamiento persistente.","Windows: administra ventanas, aplicaciones, cuentas, archivos, carpetas, dispositivos y permisos.","Archivo: contiene datos; carpeta: los organiza; acceso directo: apunta a un recurso sin ser ese recurso.","Seguridad: actualizar, bloquear sesión, usar credenciales robustas y copias de seguridad y desconfiar de adjuntos inesperados.","Extensiones y rutas: permiten localizar y reconocer formatos; cambiar el nombre de una extensión no convierte realmente el archivo."], example: 'Cerrar una aplicación libera RAM, pero borrar un acceso directo no elimina necesariamente el archivo original.', keys: ['RAM ≠ disco.', 'Archivo ≠ carpeta ≠ acceso directo.', 'Extensión ayuda a identificar el tipo de archivo, pero no garantiza que sea seguro.'] },
      { number: 10, title: 'Microsoft 365: Word y Excel', explanation: ["Word: estilos para estructura coherente, secciones para cambiar diseño y referencias para índices, notas y numeración.","Revisión: comentarios proponen o explican; control de cambios registra modificaciones; aceptar o rechazar decide el texto final.","Excel: libro contiene hojas; hojas contienen celdas organizadas en filas y columnas.","Referencias: A1 es relativa; $AWord estructura documentos con estilos, secciones, tablas, encabezados, referencias y control de cambios. Excel organiza datos en celdas, fórmulas y funciones; distingue referencias relativas, absolutas y mixtas. En colaboración importan permisos, versiones, comentarios y protección de información. fija fila y columna; $A1 fija columna y AWord estructura documentos con estilos, secciones, tablas, encabezados, referencias y control de cambios. Excel organiza datos en celdas, fórmulas y funciones; distingue referencias relativas, absolutas y mixtas. En colaboración importan permisos, versiones, comentarios y protección de información. fija fila.","Funciones: SUMA agrega cantidades; PROMEDIO calcula media; SI elige un resultado según una condición. Ordenar cambia el orden y filtrar oculta temporalmente filas que no cumplen criterio.","Colaboración: permisos de lectura o edición, historial de versiones y enlaces limitados según destinatario; compartir no significa hacer público.","Salida: guardar conserva el trabajo; exportar cambia formato, como PDF; antes de enviar se revisan datos, comentarios y permisos."], example: 'En Excel, A1 cambia al copiar; $A$1 permanece fija. En Word, un estilo de título permite índice automático y formato coherente.', keys: ['Una fórmula comienza normalmente por =.', 'No confundir guardar, exportar y compartir.', 'Excel ayuda a calcular, pero no sustituye el sistema administrativo oficial.'] },
      { number: 11, title: 'Correo electrónico e Internet', explanation: ["Internet y web: Internet conecta redes; la web es uno de sus servicios, junto al correo y otros.","URL y DNS: URL identifica un recurso; DNS traduce nombres de dominio a direcciones utilizadas por la red.","HTTPS: cifra la comunicación; un sitio fraudulento también puede tener certificado, por lo que hay que revisar el dominio.","Destinatarios: Para es principal; CC envía copia visible; CCO oculta direcciones a los demás destinatarios.","Phishing: suplantación para conseguir datos o inducir acciones; verificar por otro canal antes de abrir enlaces o entregar credenciales.","Envío seguro: comprobar dirección, adjuntos, datos personales y canal; un correo ordinario no equivale automáticamente a notificación legal."], example: 'Un mensaje urgente que pide credenciales mediante un enlace extraño es probable phishing: no se abre y se comunica por el canal corporativo.', keys: ['Correo ordinario no equivale siempre a notificación administrativa.', 'CCO protege direcciones en envíos colectivos.', 'HTTPS cifra la conexión, pero no garantiza que el sitio sea legítimo.'] },
    ],
    finalExample: 'Una persona solicita una ayuda: recibe atención accesible, la oficina registra y digitaliza, el expediente se tramita electrónicamente, se publican solo datos permitidos, el personal usa Word y Excel con seguridad y la resolución se comunica por el canal legal.',
    memory: 'Grupo V = el trabajo diario: atender, registrar, proteger, tramitar y comunicar con herramientas digitales.',
  },
];
